package fetvisuals.modules.hud;
import fetvisuals.module.*; import fetvisuals.render.*; import net.minecraft.client.MinecraftClient; import net.minecraft.client.gui.DrawContext; import net.minecraft.entity.LivingEntity;
public final class TargetHUD extends fetvisuals.module.Module {public TargetHUD(){super("TargetHUD","Nearest living target",Category.HUD);}public void onHud(DrawContext c,float d){MinecraftClient mc=MinecraftClient.getInstance();if(mc.player==null||mc.world==null)return;LivingEntity best=null;double bd=8;for(var e:mc.world.getEntitiesByClass(LivingEntity.class,mc.player.getBoundingBox().expand(8),x->x!=mc.player&&x.isAlive())){double q=mc.player.distanceTo(e);if(q<bd){bd=q;best=e;}}if(best==null)return;int x=width(c)-190,y=10;RenderUtils.rounded(c,x,y,180,54,10,0xE8181422);FontRenderer.draw(c,best.getName().getString(),x+12,y+9,0xFFEAE7F2);float hp=best.getHealth()/Math.max(1,best.getMaxHealth());RenderUtils.rect(c,x+12,y+30,(int)(150*Math.max(0,Math.min(1,hp))),6,0xFFB66DFF);FontRenderer.draw(c,String.format("%.1f HP  %.1fm",best.getHealth(),bd),x+12,y+40,0xFF96919D);}private int width(DrawContext c){return MinecraftClient.getInstance().getWindow().getScaledWidth();}}
